#!/bin/sh

set -eux pipefail

cd "$(dirname "$0")/../.."

CHAIN_ID="test-ibc-eth"
KEYRING="test"

# Store Wasm code
echo '{
 "messages": [
  {
   "@type": "/ibc.lightclients.wasm.v1.MsgStoreCode",
   "signer": "cosmos10d07y265gmmuvt4z0w9aw880jnsr700j6zn9kn",
   "wasm_byte_code": ""
  }
 ],
 "title": "ibc-eureka-op",
 "deposit": "10000000stake",
 "summary": "cw-ics08-wasm op light client",
 "expedited": false
}' > proposal.json

gaiad tx gov submit-proposal proposal.json \
  --from val1 \
  --home "$HOME/.gaia" \
  --chain-id "$CHAIN_ID" \
  --keyring-backend "$KEYRING" \
  --gas 200000000 \
  --gas-prices 1stake \
  -y

sleep 5

PROPOSAL_ID=$(
  gaiad q gov proposals -o json \
    | jq -r '.proposals | sort_by(.id | tonumber) | last | .id'
)

sleep 5

gaiad tx gov vote "$PROPOSAL_ID" yes \
  --from val1 \
  --home "$HOME/.gaia" \
  --chain-id "$CHAIN_ID" \
  --keyring-backend "$KEYRING" \
  --gas-prices 1stake \
  -y

gaiad tx gov vote "$PROPOSAL_ID" yes \
  --from val2 \
  --home "$HOME/.gaia-val2" \
  --chain-id "$CHAIN_ID" \
  --keyring-backend "$KEYRING" \
  --gas-prices 1stake \
  -y

gaiad tx gov vote "$PROPOSAL_ID" yes \
  --from val3 \
  --home "$HOME/.gaia-val3" \
  --chain-id "$CHAIN_ID" \
  --keyring-backend "$KEYRING" \
  --gas-prices 1stake \
  -y

sleep 30

CHECKSUM=$(gaiad q ibc-wasm checksums | yq '.checksums[0]')

echo "Checksum: 0x$CHECKSUM"
